WITH major_attendance AS (SELECT m_join.major_name, COUNT(DISTINCT a.link_to_member) as unique_attendees, COUNT(a.link_to_event) as total_attendance FROM member m JOIN major m_join ON m.link_to_major = m_join.major_id JOIN attendance a ON m.member_id = a.link_to_member GROUP BY m_join.major_name) SELECT major_name, CAST(total_attendance AS FLOAT) / unique_attendees as attendance_rate FROM major_attendance ORDER BY attendance_rate DESC;
